/**
 * This site's own Content-Security-Policy, delivered in two parts:
 *
 * 1. A <meta> policy generated by Astro (security.csp) on every page. Astro adds
 *    script-src / style-src with 'self' and the hashes of its inline scripts and styles,
 *    on top of the directives below.
 * 2. An HTTP header set by CloudFront (see infra/), for what a <meta> policy cannot do:
 *    frame-ancestors is ignored in <meta>.
 *
 * Browsers enforce both: a resource must be allowed by each of them.
 */
export const META_DIRECTIVES = [
  "default-src 'self'",
  "img-src 'self' data:",
  "font-src 'self'",
  "connect-src 'self'",
  "object-src 'none'",
  "base-uri 'none'",
  "form-action 'none'",
  // Scripts can't write raw HTML (innerHTML and the like); in the <meta> part so the e2e suite enforces it.
  "require-trusted-types-for 'script'",
];

export const HEADER_POLICY = "frame-ancestors 'none'; object-src 'none'; base-uri 'none'; upgrade-insecure-requests";
